#!/bin/sh
# orbit join: sets up this host as an N6 responder for an orbit server
# (ADR-0009). Generated by orbit serve for one join token; it expires, and
# the server keeps only its hash.
#
# It prints a plan and changes nothing until the plan is confirmed: on
# /dev/tty, or with --yes. Options: --yes, --dry-run, --n6-ip IP,
# --bind HOST:PORT, --no-firewall, --no-route, --no-systemd, --reregister.
#
# Everything is in main, called on the last line only: a download cut short
# runs nothing. A partial main is a syntax error, and main refuses to run
# unless its call arrived whole, which ends with this render's own
# sentinel (every shorter prefix of the call ends with something else).
main() {
	set -eu
	umask 077
	PATH='/usr/sbin:/usr/bin:/sbin:/bin'
	export PATH
	eval "ORBIT_LAST=\${$#}"
	[ "$ORBIT_LAST" = '--orbit-end-00112233445566778899aabbccddeeff' ] || {
		echo "orbit join: this script is incomplete; download it again" >&2
		exit 1
	}

	ORBIT_SERVER='https://192.0.2.10:8412'
	ORBIT_PIN='sha256//47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFU='
	ORBIT_PIN_RAW='sha256/47DEQpj8HBSa+/TImW+5JCeuQeRkm5NMpJWZG3hSuFU='
	ORBIT_TOKEN='oj1_AAAAAAAAAAAAAAAAAAAAAA'
	ORBIT_NAME='app1'
	SHA256_AMD64='e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'
	SHA256_ARM64='e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'
	UE_POOLS='10.250.0.0/16'
	UPF_N6='198.51.100.1'
	N6_SUBNET='198.51.100.0/24'
	MGMT_HOST='192.0.2.10'
	MGMT_IS_IP='yes'
	BIND_PORT='9551'
	ROOT=''

	LIB=/usr/local/lib/orbit
	UNIT=/etc/systemd/system/orbit-responder.service
	CONF=/etc/orbit/responder.yaml
	TTY=$ROOT/dev/tty

	die() {
		echo "orbit join: $*" >&2
		exit 1
	}
	say() {
		echo "orbit join: $*"
	}

	YES='' DRY='' N6_IP='' BIND='' NO_FW='' NO_ROUTE='' NO_SYSTEMD='' REREGISTER=''
	while [ $# -gt 1 ]; do
		case $1 in
		--yes) YES=1 ;;
		--dry-run) DRY=1 ;;
		--no-firewall) NO_FW=1 ;;
		--no-route) NO_ROUTE=1 ;;
		--no-systemd) NO_SYSTEMD=1 ;;
		--reregister) REREGISTER=1 ;;
		--n6-ip | --bind)
			[ $# -gt 2 ] || die "$1 needs a value"
			case $1 in --n6-ip) N6_IP=$2 ;; *) BIND=$2 ;; esac
			shift
			;;
		--n6-ip=*) N6_IP=${1#*=} ;;
		--bind=*) BIND=${1#*=} ;;
		*) die "unknown option $1 (options: --yes --dry-run --n6-ip IP --bind HOST:PORT --no-firewall --no-route --no-systemd --reregister)" ;;
		esac
		shift
	done

	# Values that reach a command line, the helper or the unit: addresses,
	# CIDRs, interface names and ports only, so none can carry shell or
	# nft syntax.
	is_addr() {
		case $1 in '' | *[!0-9A-Fa-f.:]*) return 1 ;; esac
	}
	is_cidr() {
		case $1 in '' | *[!0-9A-Fa-f.:/]*) return 1 ;; esac
	}
	is_dev() {
		case $1 in '' | *[!A-Za-z0-9_.@-]*) return 1 ;; esac
	}
	is_port() {
		case $1 in '' | *[!0-9]*) return 1 ;; esac
		[ "$1" -ge 1 ] && [ "$1" -le 65535 ]
	}
	is_digits() {
		case $1 in '' | *[!0-9]*) return 1 ;; esac
	}
	# stale_id_ok ID: whether ID is exactly an orbit-join rule ID of the
	# form this script writes: orbit-join control|data DEV CIDR PORT[-PORT],
	# or orbit-join icmp DEV CIDR echo.
	stale_id_ok() {
		case $1 in '' | *[!A-Za-z0-9\ ./:_-]*) return 1 ;; esac
		# shellcheck disable=SC2086 # the five words, split (no globbing: checked above)
		set -- $1
		if [ $# != 5 ] || [ "$1" != orbit-join ]; then return 1; fi
		case $2 in control | data | icmp) ;; *) return 1 ;; esac
		if ! is_dev "$3" || ! is_cidr "$4"; then return 1; fi
		if [ "$2" = icmp ]; then
			[ "$5" = echo ]
			return
		fi
		case $5 in
		*-*) is_port "${5%-*}" && is_port "${5#*-}" ;;
		*) is_port "$5" ;;
		esac
	}
	[ -z "$N6_IP" ] || is_addr "$N6_IP" || die "--n6-ip $N6_IP: want an IP address"
	# The values the server rendered, checked here too before first use.
	is_addr "$UPF_N6" || die "the UPF's N6 address $(printf '%s' "$UPF_N6") is not an IP address"
	is_port "$BIND_PORT" || die "the responder port $(printf '%s' "$BIND_PORT") is not a port"
	if [ "$MGMT_IS_IP" = yes ]; then
		is_addr "$MGMT_HOST" || die "the server's address $(printf '%s' "$MGMT_HOST") is not an IP address"
	else
		case $MGMT_HOST in '' | *[!A-Za-z0-9.-]*) die "the server's name $(printf '%s' "$MGMT_HOST") is not a host name" ;; esac
	fi
	for P in $UE_POOLS $N6_SUBNET; do
		is_cidr "$P" || die "$P: not a CIDR"
	done

	ME=$(id -u)
	[ "$ME" = 0 ] || [ -n "$DRY" ] || die "run this as root (… | sudo sh), or add --dry-run to see the plan"

	[ "$(uname -s)" = Linux ] || die "Linux only; this host runs $(uname -s)"
	case "$(uname -m)" in
	x86_64 | amd64) ARCH=amd64 WANT=$SHA256_AMD64 ;;
	aarch64 | arm64) ARCH=arm64 WANT=$SHA256_ARM64 ;;
	*) die "amd64 or arm64 only; this host is $(uname -m)" ;;
	esac
	[ -n "$WANT" ] || die "the server has no orbit binary for linux/$ARCH (orbit serve --join-binaries)"
	command -v curl >/dev/null 2>&1 || die "curl is required"
	command -v sha256sum >/dev/null 2>&1 || die "sha256sum is required to verify the orbit binary (coreutils)"
	command -v ip >/dev/null 2>&1 || die "ip (iproute2) is required"

	# Everything downloaded or prepared goes in a private directory, removed
	# on exit. Nothing outside it changes before the plan is confirmed.
	WORK=$(mktemp -d) || die "mktemp -d failed"
	trap 'rm -rf "$WORK"' EXIT
	trap 'exit 1' HUP INT TERM

	# The URL holds the token: curl reads it from a 0600 file in the work
	# directory, never its argv (which ps shows to every user).
	printf 'url = "%s"\n' "$ORBIT_SERVER/join/$ORBIT_TOKEN/bin/$ARCH" >"$WORK/fetch"
	# -q, first, keeps root's ~/.curlrc out of every curl here.
	curl -q -fsS --proto '=https' -k --pinnedpubkey "$ORBIT_PIN" -o "$WORK/orbit" -K "$WORK/fetch" ||
		die "downloading orbit for linux/$ARCH failed"
	# Checked before anything else touches it. It is made executable and
	# run (`orbit version`) only after the plan is confirmed: nothing
	# downloaded runs before then.
	GOT=$(sha256sum "$WORK/orbit" | cut -d ' ' -f 1)
	[ "$GOT" = "$WANT" ] || die "the downloaded orbit's SHA-256 is $GOT, want $WANT; refusing to run it"

	# The responder's name: the token's, else this host's short name.
	NAME=$ORBIT_NAME
	[ -n "$NAME" ] || NAME=$(uname -n | cut -d . -f 1)
	case $NAME in
	[A-Za-z0-9]*) ;;
	*) die "this host's name $(printf '%s' "$NAME") is not a responder name; issue the token with orbit join create --name" ;;
	esac
	case $NAME in *[!A-Za-z0-9_-]*) die "this host's name $(printf '%s' "$NAME") is not a responder name; issue the token with orbit join create --name" ;; esac
	[ ${#NAME} -le 63 ] || die "this host's name is longer than 63 characters; issue the token with orbit join create --name"
	say "verified orbit for linux/$ARCH (sha256 $WANT)"
	say "responder $NAME; UE pools $UE_POOLS via $UPF_N6, N6 $N6_SUBNET"

	# innet IP CIDR: whether IP is inside CIDR, either family, in POSIX awk
	# (no bit operators: both are compared as strings of bits).
	INNET='
	function hexval(c) { return index("0123456789abcdef", tolower(c)) - 1 }
	function tobits(v, n,   b, k) { b = ""; for (k = 0; k < n; k++) { b = (v % 2) b; v = int(v / 2) } return b }
	function bits4(ip,   p, i, s) {
		if (split(ip, p, ".") != 4) return ""
		s = ""
		for (i = 1; i <= 4; i++) { if (p[i] !~ /^[0-9]+$/ || p[i] > 255) return ""; s = s tobits(p[i] + 0, 8) }
		return s
	}
	function bits6(ip,   h, nh, lp, rp, nl, nr, g, ng, i, j, c, v, s) {
		nh = split(ip, h, "::")
		if (nh > 2) return ""
		nl = 0; nr = 0
		if (h[1] != "") nl = split(h[1], lp, ":")
		if (nh == 2 && h[2] != "") nr = split(h[2], rp, ":")
		if (nh == 1 && nl != 8) return ""
		ng = 0
		for (i = 1; i <= nl; i++) g[++ng] = lp[i]
		if (nh == 2) for (i = 0; i < 8 - nl - nr; i++) g[++ng] = "0"
		for (i = 1; i <= nr; i++) g[++ng] = rp[i]
		if (ng != 8) return ""
		s = ""
		for (i = 1; i <= 8; i++) {
			if (length(g[i]) < 1 || length(g[i]) > 4) return ""
			v = 0
			for (j = 1; j <= length(g[i]); j++) { c = hexval(substr(g[i], j, 1)); if (c < 0) return ""; v = v * 16 + c }
			s = s tobits(v, 16)
		}
		return s
	}
	function bits(ip) { return index(ip, ":") ? bits6(ip) : bits4(ip) }
	function innet(ip, cidr,   p, a, b, n) {
		if (split(cidr, p, "/") != 2) return 0
		n = p[2] + 0; a = bits(ip); b = bits(p[1])
		if (a == "" || b == "" || length(a) != length(b) || n > length(a)) return 0
		return substr(a, 1, n) == substr(b, 1, n)
	}'
	innet() {
		awk -v ip="$1" -v net="$2" "$INNET"' BEGIN { exit !innet(ip, net) }'
	}
	# q VALUE: VALUE as one single-quoted shell word. Every value written
	# into the apply file or the helper goes through it.
	q() {
		printf "'%s'" "$(printf '%s' "$1" | sed "s/'/'\\\\''/g")"
	}
	# oneline TEXT: TEXT's lines joined by spaces.
	oneline() {
		printf '%s\n' "$1" | awk 'NF { printf "%s%s", sep, $0; sep = " " }'
	}
	# fam ADDR: 4 or 6.
	fam() {
		case $1 in *:*) echo 6 ;; *) echo 4 ;; esac
	}
	# ipf ADDR: ip's family flag for ADDR.
	ipf() {
		case $1 in *:*) echo -6 ;; *) echo -4 ;; esac
	}
	# field LINE KEY: the word after KEY in an `ip -o route get` line.
	field() {
		printf '%s\n' "$1" | awk -v k="$2" '{ for (i = 1; i < NF; i++) if ($i == k) { print $(i + 1); exit } }'
	}
	# is_local ADDR: whether ADDR is one of this host's addresses.
	is_local() {
		ip -o addr show | awk '{ split($4, a, "/"); print a[1] }' | grep -qxF "$1"
	}

	# The N6 IP: the source this host routes to the UPF's N6 address from,
	# unless --n6-ip says otherwise. Ambiguity is a refusal, never a guess.
	if [ -z "$N6_IP" ]; then
		R=$(ip -o "$(ipf "$UPF_N6")" route get "$UPF_N6" 2>/dev/null) ||
			die "no route to the UPF's N6 address $UPF_N6; route it, or pass --n6-ip"
		N6_DEV=$(field "$R" dev) N6_IP=$(field "$R" src) VIA=$(field "$R" via)
		if [ -z "$N6_DEV" ] || [ -z "$N6_IP" ]; then
			die "the route to $UPF_N6 names no interface or source: $R; pass --n6-ip"
		fi
		if [ -n "$VIA" ] && ! innet "$N6_IP" "$N6_SUBNET"; then
			die "this host reaches the UPF's N6 address $UPF_N6 only through gateway $VIA (from $N6_IP on $N6_DEV, outside N6 $N6_SUBNET); pass --n6-ip if that is right"
		fi
		MINE=$(ip -o addr show dev "$N6_DEV" scope global | awk '{ split($4, a, "/"); print a[1] }' |
			while read -r A; do if innet "$A" "$N6_SUBNET"; then echo "$A"; fi; done)
		if [ "$(printf '%s\n' "$MINE" | grep -c .)" -gt 1 ]; then
			die "$N6_DEV has several addresses in N6 $N6_SUBNET ($(oneline "$MINE")); pass --n6-ip to choose one"
		fi
		N6_WHY="from the route to the UPF's N6 address $UPF_N6; override with --n6-ip"
	else
		is_local "$N6_IP" || die "--n6-ip $N6_IP is not an address of this host"
		R=$(ip -o "$(ipf "$UPF_N6")" route get "$UPF_N6" from "$N6_IP" 2>/dev/null) ||
			die "no route to the UPF's N6 address $UPF_N6 from --n6-ip $N6_IP"
		N6_DEV=$(field "$R" dev)
		N6_WHY="from --n6-ip"
	fi
	is_addr "$N6_IP" || die "N6 IP $N6_IP: not an IP address"
	is_dev "$N6_DEV" || die "interface name $N6_DEV is not supported (letters, digits, _ . @ - only)"

	# The server's address, as this host reaches it: an IP as given; a name
	# with one address per family, the family the host has a route to
	# (IPv4 first). Several addresses in one family is a refusal.
	if [ "$MGMT_IS_IP" = yes ]; then
		MGMT_IP=$MGMT_HOST
	else
		V4=$(getent ahostsv4 "$MGMT_HOST" 2>/dev/null | awk '{ print $1 }' | sort -u) || V4=''
		V6=$(getent ahostsv6 "$MGMT_HOST" 2>/dev/null | awk '$1 ~ /:/ && $1 !~ /^::ffff:/ { print $1 }' | sort -u) || V6=''
		for L in "$V4" "$V6"; do
			[ "$(printf '%s\n' "$L" | grep -c .)" -le 1 ] ||
				die "the server's name $MGMT_HOST has several addresses in one family ($(oneline "$L")), so this host cannot tell which one the server dials from; issue the token again with orbit join create --mgmt <ip>"
		done
		MGMT_IP=''
		for A in $V4 $V6; do
			if ip -o "$(ipf "$A")" route get "$A" >/dev/null 2>&1; then
				MGMT_IP=$A
				break
			fi
		done
		[ -n "$MGMT_IP" ] || die "the server's name $MGMT_HOST has no address this host routes to"
	fi
	is_addr "$MGMT_IP" || die "the server's address $MGMT_IP is not an IP address"

	# The control bind: the source toward the server, unless --bind says
	# otherwise, on the responder's port.
	if [ -z "$BIND" ]; then
		R=$(ip -o "$(ipf "$MGMT_IP")" route get "$MGMT_IP" 2>/dev/null) ||
			die "no route to the server at $MGMT_IP; pass --bind"
		CTL_IP=$(field "$R" src) CTL_DEV=$(field "$R" dev) CTL_PORT=$BIND_PORT
		if [ -z "$CTL_IP" ] || [ -z "$CTL_DEV" ]; then
			die "the route to $MGMT_IP names no interface or source: $R; pass --bind"
		fi
		BIND_WHY="from the route to the server at $MGMT_IP; override with --bind"
	else
		case $BIND in
		\[*\]:*) CTL_IP=${BIND#\[} CTL_IP=${CTL_IP%%\]*} CTL_PORT=${BIND##*\]:} ;;
		*:*:*) die "--bind $BIND: bracket an IPv6 address, [addr]:port" ;;
		*:*) CTL_IP=${BIND%:*} CTL_PORT=${BIND##*:} ;;
		*) die "--bind $BIND: want HOST:PORT" ;;
		esac
		is_addr "$CTL_IP" || die "--bind $BIND: want an IP address and a port"
		is_local "$CTL_IP" || die "--bind $CTL_IP is not an address of this host"
		R=$(ip -o "$(ipf "$MGMT_IP")" route get "$MGMT_IP" from "$CTL_IP" 2>/dev/null) ||
			die "no route to the server at $MGMT_IP from --bind $CTL_IP"
		CTL_DEV=$(field "$R" dev)
		BIND_WHY="from --bind"
	fi
	is_port "$CTL_PORT" || die "control port $CTL_PORT: want 1-65535"
	is_dev "$CTL_DEV" || die "interface name $CTL_DEV is not supported (letters, digits, _ . @ - only)"
	[ "$(fam "$CTL_IP")" = "$(fam "$MGMT_IP")" ] || die "--bind $CTL_IP and the server's address $MGMT_IP are different families"
	case $CTL_IP in *:*) LISTEN="[$CTL_IP]:$CTL_PORT" ;; *) LISTEN="$CTL_IP:$CTL_PORT" ;; esac

	say "N6 IP $N6_IP on $N6_DEV ($N6_WHY)"
	say "control bind $LISTEN on $CTL_DEV ($BIND_WHY)"

	# The plan: steps, each a title and the exact commands or file text,
	# shown before anything runs; steps already in place are listed as ok.
	PLAN=$WORK/plan APPLY=$WORK/apply HELPER=$WORK/helper
	: >"$PLAN"
	: >"$APPLY"
	: >"$HELPER"
	N=0
	# inert TEXT: refuses TEXT unless it holds no shell syntax beyond the
	# quotes and braces the plan's own commands use. Every step title and
	# command passes it before it is written to the apply file.
	inert() {
		case $1 in
		*[\$\`\;\&\|\<\>\\]* | *"
"*) die "refusing a plan line that is not inert: $(printf '%s' "$1" | tr -c '[:print:]' '?')" ;;
		esac
	}
	step() {
		inert "$1"
		case $1 in *"'"*) die "refusing a step title with a quote: $(printf '%s' "$1" | tr -c '[:print:]' '?')" ;; esac
		N=$((N + 1))
		printf '  %d. %s\n' "$N" "$1" >>"$PLAN"
		printf "begin %d '%s'\n" "$N" "$1" >>"$APPLY"
	}
	# cmd LINE: a command of the current step, shown and run as given.
	cmd() {
		inert "$1"
		printf '       %s\n' "$1" >>"$PLAN"
		printf '%s || fail\n' "$1" >>"$APPLY"
	}
	# show TEXT: a line of the current step that is not a command.
	show() {
		printf '       %s\n' "$1" >>"$PLAN"
	}
	ok() {
		printf '  ok: %s\n' "$1" >>"$PLAN"
	}
	# helper LINE: a line of join-net.sh, the unit's ExecStartPre.
	helper() {
		# Its own fixed syntax aside (the pipe to grep, the || fallback, the
		# 2>/dev/null), a helper line must be as inert as a plan line.
		inert "$(printf '%s' "$1" | sed -e 's| 2>/dev/null||g' -e 's/ || / /g' -e 's/ | grep -qF / /g')"
		printf '%s\n' "$1" >>"$HELPER"
	}

	# The binary.
	if [ -f "$ROOT$LIB/orbit" ] && [ "$(sha256sum "$ROOT$LIB/orbit" | cut -d ' ' -f 1)" = "$WANT" ]; then
		ok "orbit is installed as $LIB/orbit (sha256 $WANT)"
	else
		step "install the verified orbit as $LIB/orbit (sha256 $WANT)"
		printf '%s || fail\n' "install -d -m 0755 '$ROOT$LIB'" "install -m 0755 '$WORK/orbit' '$ROOT$LIB/orbit'" >>"$APPLY"
	fi

	# The return route for each UE pool, through the UPF.
	if [ -n "$NO_ROUTE" ]; then
		ok "routes: skipped (--no-route)"
	else
		for P in $UE_POOLS; do
			[ "$(fam "$P")" = "$(fam "$UPF_N6")" ] || die "UE pool $P and the UPF's N6 address $UPF_N6 are different families"
			LINE="ip $(ipf "$P") route replace $(q "$P") via $(q "$UPF_N6") dev $(q "$N6_DEV")"
			helper "$LINE"
			NOW=$(ip "$(ipf "$P")" route show exact "$P" 2>/dev/null) || NOW=''
			case " $NOW " in
			*" via $UPF_N6 dev $N6_DEV "*) ok "route $P via $UPF_N6 dev $N6_DEV" ;;
			*)
				step "route UE pool $P back through the UPF"
				cmd "$LINE"
				[ -z "$NOW" ] || show "(replaces: $(oneline "$NOW"))"
				;;
			esac
		done
	fi

	# The firewall: rules for the control port from the server, and for the
	# data ports from the UE pools and the N6 subnet, each bound to its
	# interface too. Where input is not filtered there is nothing to open.
	# The data ports: the host's ephemeral range, which the responder's
	# receivers bind from; the firewall opens it and the registration reports it.
	RANGE=$(cat "$ROOT/proc/sys/net/ipv4/ip_local_port_range" 2>/dev/null) || RANGE=''
	# shellcheck disable=SC2086 # the two numbers, split
	set -- $RANGE
	LO=${1:-} HI=${2:-}
	if ! is_port "$LO" || ! is_port "$HI"; then
		die "cannot read this host's ephemeral port range (net.ipv4.ip_local_port_range)"
	fi
	RANGE_WHY="data ports $LO-$HI: this host's ephemeral range (net.ipv4.ip_local_port_range), since the responder's receivers bind ephemeral ports"
	# rules FAMILY: "control DEV SRC PORT", "data DEV SRC LO-HI" and
	# "icmp DEV SRC echo" for the sources of FAMILY. The ICMP echo is what
	# orbit target probe's UE-to-N6 echo needs.
	rules() {
		if [ "$(fam "$MGMT_IP")" = "$1" ]; then
			case $1 in 4) S=$MGMT_IP/32 ;; *) S=$MGMT_IP/128 ;; esac
			echo "control $CTL_DEV $S $CTL_PORT"
		fi
		for S in $UE_POOLS $N6_SUBNET; do
			if [ "$(fam "$S")" = "$1" ]; then
				echo "data $N6_DEV $S $LO-$HI"
				echo "icmp $N6_DEV $S echo"
			fi
		done
	}
	if [ -n "$NO_FW" ]; then
		ok "firewall: skipped (--no-firewall)"
	elif [ "$ME" != 0 ]; then
		printf '  ?: firewall: needs root to inspect (run as root to see this step)\n' >>"$PLAN"
	elif command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q '^Status: active'; then
		echo "orbit join: ufw manages this host's firewall; this script does not edit it. Run these, then rerun with --no-firewall:" >&2
		for F in 4 6; do
			rules $F | while read -r KIND DEV S PORT; do
				if [ "$KIND" = control ]; then
					echo "  ufw allow in on $DEV from $S to any port $PORT proto tcp" >&2
				elif [ "$KIND" = icmp ]; then
					echo "  (ICMP echo-request from $S on $DEV: ufw allows it by default, in /etc/ufw/before.rules; keep that)" >&2
				else
					echo "  ufw allow in on $DEV from $S to any port $(echo "$PORT" | tr - :) proto udp" >&2
					echo "  ufw allow in on $DEV from $S to any port $(echo "$PORT" | tr - :) proto tcp" >&2
				fi
			done
		done
		echo "  ($RANGE_WHY)" >&2
		exit 1
	elif command -v firewall-cmd >/dev/null 2>&1 && [ "$(firewall-cmd --state 2>/dev/null)" = running ]; then
		echo "orbit join: firewalld manages this host's firewall; this script does not edit it. Run these, then rerun with --no-firewall:" >&2
		for F in 4 6; do
			rules $F | while read -r KIND DEV S PORT; do
				case $F in 4) RF=ipv4 ;; *) RF=ipv6 ;; esac
				if [ "$KIND" = control ]; then
					echo "  firewall-cmd --permanent --add-rich-rule='rule family=\"$RF\" source address=\"$S\" port port=\"$PORT\" protocol=\"tcp\" accept'" >&2
				elif [ "$KIND" = icmp ]; then
					echo "  firewall-cmd --permanent --add-rich-rule='rule family=\"$RF\" source address=\"$S\" icmp-type name=\"echo-request\" accept'" >&2
				else
					for PR in udp tcp; do
						echo "  firewall-cmd --permanent --add-rich-rule='rule family=\"$RF\" source address=\"$S\" port port=\"$PORT\" protocol=\"$PR\" accept'" >&2
					done
				fi
			done
		done
		echo "  firewall-cmd --reload" >&2
		IFACES="$CTL_DEV and $N6_DEV"
		[ "$CTL_DEV" != "$N6_DEV" ] || IFACES=$CTL_DEV
		echo "  (firewalld binds interfaces through zones: put $IFACES in the zone these rules go in. $RANGE_WHY)" >&2
		echo "  (an icmp-block on echo-request in that zone wins over the accept above: check with firewall-cmd --zone=<zone> --query-icmp-block=echo-request, and remove it with --remove-icmp-block=echo-request)" >&2
		exit 1
	else
		# Whether input is filtered, per family. It is provably not only when
		# every nft input filter base chain (other than iptables-nft's own
		# ip/ip6 filter INPUT) has policy accept and no rules, and iptables'
		# INPUT has policy ACCEPT and no rules. Anything else, jumps, gotos
		# and vmaps among it, counts as filtered: nothing here tries to work
		# out whether a rule drops. Output this cannot read is a refusal.
		CHAINS=''
		if command -v nft >/dev/null 2>&1; then
			RS=$(nft list ruleset 2>/dev/null) || die "nft list ruleset failed"
			CHAINS=$(printf '%s\n' "$RS" | awk '
				/^table / { if (NF < 3 || in_ch) bad = 1; fam = $2; tbl = $3; next }
				/^[ \t]*chain / { if (in_ch) bad = 1; ch = $2; base = 0; acc = 1; nrules = 0; in_ch = 1; depth = 1; next }
				in_ch {
					# Brace depth: a line at depth 1 is the chain'"'"'s own (its type
					# line, a rule, or its closing brace); deeper lines are a
					# multi-line set or map inside a rule.
					line = $0
					opens = gsub(/[{]/, "", line)
					line = $0
					closes = gsub(/[}]/, "", line)
					if (depth == 1 && $0 ~ /type filter hook input/) {
						base = 1
						if ($0 ~ /policy/ && $0 !~ /policy accept/) acc = 0
						next
					}
					if (depth == 1 && NF && $1 !~ /^#/ && $1 != "}") nrules++
					depth += opens - closes
					if (depth <= 0) {
						if (base && !((fam == "ip" || fam == "ip6") && tbl == "filter" && ch == "INPUT"))
							print fam, tbl, ch, (acc && nrules == 0) ? "open" : "filtered"
						in_ch = 0
					}
					next
				}
				!in_ch && /hook input/ { bad = 1 }
				END { if (in_ch) bad = 1; if (bad) print "unparsed" }')
		fi
		# ipt_state CMD: none (no CMD), open, filtered or unparsed, for INPUT.
		ipt_state() {
			if ! command -v "$1" >/dev/null 2>&1; then
				echo none
				return
			fi
			OUT=$("$1" -S INPUT 2>/dev/null) || OUT=''
			case $OUT in
			"-P INPUT ACCEPT") echo open ;;
			"-P INPUT "*) echo filtered ;;
			*) echo unparsed ;;
			esac
		}
		# manual F WHY: the refusal that prints the rules to add by hand.
		manual() {
			echo "orbit join: $2; this script does not choose for you. Allow these where they belong, then rerun with --no-firewall:" >&2
			rules "$1" | while read -r KIND DEV S PORT; do
				if [ "$KIND" = control ]; then
					echo "  tcp to port $PORT, in on $DEV, from $S" >&2
				elif [ "$KIND" = icmp ]; then
					echo "  icmp echo-request, in on $DEV, from $S" >&2
				else
					echo "  tcp and udp to ports $PORT, in on $DEV, from $S" >&2
				fi
			done
			echo "  ($RANGE_WHY)" >&2
			exit 1
		}
		WANTIDS=$(for F in 4 6; do rules $F; done | while read -r KIND DEV S PORT; do printf '|orbit-join %s %s %s %s|' "$KIND" "$DEV" "$S" "$PORT"; done)
		SWEPT=''
		for F in 4 6; do
			[ -n "$(rules $F)" ] || continue
			case $F in 4) IPT=iptables NF=ip ;; *) IPT=ip6tables NF=ip6 ;; esac
			IS=$(ipt_state $IPT)
			if printf '%s\n' "$CHAINS" | grep -qx unparsed || [ "$IS" = unparsed ]; then
				manual $F "cannot read this host's IPv$F input firewall (nft list ruleset, $IPT -S INPUT)"
			fi
			MINE=$(printf '%s\n' "$CHAINS" | awk -v nf="$NF" '($1 == "inet" || $1 == nf) && $4 == "filtered" { print $1, $2, $3 }')
			NC=$(printf '%s\n' "$MINE" | grep -c . || true)
			TOTAL=$NC
			[ "$IS" != filtered ] || TOTAL=$((TOTAL + 1))
			if [ "$TOTAL" -gt 1 ]; then
				WHO=$(printf '%s\n' "$MINE" | awk 'NF { printf "%s%s %s %s", sep, $1, $2, $3; sep = "; " }')
				[ "$IS" != filtered ] || WHO="${WHO:+$WHO; }$IPT INPUT"
				manual $F "several chains filter IPv$F input on this host ($WHO)"
			elif [ "$NC" = 1 ]; then
				# shellcheck disable=SC2086 # family, table, chain
				set -- $MINE
				CF=$1 CT=$2 CC=$3
				# The names come from the host's ruleset and reach commands and
				# the helper: plain nft identifiers only.
				case $CF in inet | ip | ip6) ;; *) die "unexpected nft family in: $(printf '%s' "$MINE")" ;; esac
				for X in "$CT" "$CC"; do
					case $X in
					[A-Za-z_]*) ;;
					*) die "nft table or chain name not supported: $(printf '%s' "$X")" ;;
					esac
					case $X in *[!A-Za-z0-9_.-]*) die "nft table or chain name not supported: $(printf '%s' "$X")" ;; esac
				done
				HAVE=$(nft -a list chain "$CF" "$CT" "$CC" 2>/dev/null) || die "nft list chain $CF $CT $CC failed"
				CHAIN="$(q "$CF") $(q "$CT") $(q "$CC")"
				for R in $(rules $F | tr ' ' '|'); do
					KIND=${R%%|*} R=${R#*|} DEV=${R%%|*} R=${R#*|} S=${R%%|*} PORT=${R#*|}
					ID="orbit-join $KIND $DEV $S $PORT"
					if [ "$KIND" = control ]; then
						RULE="iifname \"$DEV\" $NF saddr $S tcp dport $PORT accept comment \"$ID\""
					elif [ "$KIND" = icmp ]; then
						if [ "$F" = 4 ]; then ICMPT="icmp type echo-request"; else ICMPT="icmpv6 type echo-request"; fi
						RULE="iifname \"$DEV\" $NF saddr $S $ICMPT accept comment \"$ID\""
					else
						RULE="iifname \"$DEV\" $NF saddr $S meta l4proto { tcp, udp } th dport $PORT accept comment \"$ID\""
					fi
					helper "nft list chain $CHAIN | grep -qF $(q "comment \"$ID\"") || nft insert rule $CHAIN $(q "$RULE")"
					if printf '%s\n' "$HAVE" | grep -qF "comment \"$ID\""; then
						ok "firewall: $ID (in $CF $CT $CC)"
					else
						if [ "$KIND" = control ]; then
							step "firewall: allow control traffic (tcp) on $DEV from $S to port $PORT"
						elif [ "$KIND" = icmp ]; then
							step "firewall: allow ICMP echo on $DEV from $S (for orbit target probe)"
						else
							step "firewall: allow data traffic (tcp, udp) on $DEV from $S to ports $PORT"
						fi
						cmd "nft insert rule $CHAIN $(q "$RULE")"
						show "inserted into $CF $CT $CC (your ruleset)"
						[ "$KIND" != data ] || show "($RANGE_WHY)"
					fi
				done
				# orbit-join rules from an earlier join that this plan no longer
				# has, swept once per chain.
				case $SWEPT in *"|$CF $CT $CC|"*) continue ;; esac
				SWEPT="$SWEPT|$CF $CT $CC|"
				printf '%s\n' "$HAVE" | sed -n 's/.*comment "\(orbit-join [^"]*\)".*# handle \([0-9][0-9]*\)$/\2|\1/p' |
					while IFS='|' read -r H ID; do
						case $WANTIDS in *"|$ID|"*) ;; *) echo "$H|$ID" ;; esac
					done >"$WORK/stale"
				while IFS='|' read -r H ID; do
					# Only an ID of the exact form this script writes, and a
					# numeric handle, becomes a step; anything else is left alone
					# and shown, inert.
					if stale_id_ok "$ID" && is_digits "$H"; then
						step "firewall: remove the earlier rule \"$ID\" from $CF $CT $CC"
						cmd "nft delete rule $CHAIN handle $(q "$H")"
					else
						printf '  note: left alone, a rule in %s %s %s whose orbit-join comment this script did not write: %s\n' \
							"$CF" "$CT" "$CC" "$ID" >>"$PLAN"
					fi
				done <"$WORK/stale"
			elif [ "$IS" = filtered ]; then
				# Each rule as -S prints it (to compare) and as the command adds
				# it (every value quoted).
				rules $F | while read -r KIND DEV S PORT; do
					if [ "$KIND" = control ]; then
						printf '%s\t%s\n' "-A ORBIT-JOIN -s $S -i $DEV -p tcp -m tcp --dport $PORT -j ACCEPT" \
							"-s $(q "$S") -i $(q "$DEV") -p tcp -m tcp --dport $(q "$PORT") -j ACCEPT"
					elif [ "$KIND" = icmp ]; then
						# As -S prints them: the echo request is type 8 (ICMPv6: 128).
						if [ "$F" = 4 ]; then MI="-p icmp -m icmp --icmp-type 8"; else MI="-p ipv6-icmp -m icmp6 --icmpv6-type 128"; fi
						printf '%s\t%s\n' "-A ORBIT-JOIN -s $S -i $DEV $MI -j ACCEPT" "-s $(q "$S") -i $(q "$DEV") $MI -j ACCEPT"
					else
						P2=$(echo "$PORT" | tr - :)
						for PR in udp tcp; do
							printf '%s\t%s\n' "-A ORBIT-JOIN -s $S -i $DEV -p $PR -m $PR --dport $P2 -j ACCEPT" \
								"-s $(q "$S") -i $(q "$DEV") -p $PR -m $PR --dport $(q "$P2") -j ACCEPT"
						done
					fi
				done >"$WORK/ipt"
				WANTRULES=$(cut -f 1 "$WORK/ipt")
				HAVE=$($IPT -S ORBIT-JOIN 2>/dev/null) || HAVE=''
				helper "$IPT -N ORBIT-JOIN 2>/dev/null || true"
				while IFS="$(printf '\t')" read -r _ A; do
					helper "$IPT -C ORBIT-JOIN $A 2>/dev/null || $IPT -A ORBIT-JOIN $A"
				done <"$WORK/ipt"
				helper "$IPT -C INPUT -m comment --comment orbit-join -j ORBIT-JOIN 2>/dev/null || $IPT -I INPUT 1 -m comment --comment orbit-join -j ORBIT-JOIN"
				if [ "$HAVE" = "$(printf '%s\n%s' "-N ORBIT-JOIN" "$WANTRULES")" ]; then
					ok "firewall: $IPT chain ORBIT-JOIN holds this plan's rules"
				else
					step "firewall: $IPT chain ORBIT-JOIN with the control and data rules"
					if [ -z "$HAVE" ]; then cmd "$IPT -N ORBIT-JOIN"; else cmd "$IPT -F ORBIT-JOIN"; fi
					while IFS="$(printf '\t')" read -r _ A; do cmd "$IPT -A ORBIT-JOIN $A"; done <"$WORK/ipt"
					show "($RANGE_WHY)"
				fi
				if $IPT -C INPUT -m comment --comment orbit-join -j ORBIT-JOIN 2>/dev/null; then
					ok "firewall: $IPT INPUT jumps to ORBIT-JOIN"
				else
					step "firewall: $IPT INPUT jumps to ORBIT-JOIN first"
					cmd "$IPT -I INPUT 1 -m comment --comment orbit-join -j ORBIT-JOIN"
				fi
			else
				ok "firewall: IPv$F input is not filtered on this host (no input rules, policy accept); nothing to open"
			fi
		done
	fi

	# The join token, for the registration: in the private work directory,
	# mode 0600, never on a command line.
	printf '%s\n' "$ORBIT_TOKEN" >"$WORK/token"

	# The responder's config: none yet (a new registration), one already
	# (registered; --reregister rotates its secrets), or one in flight from
	# an earlier run that did not finish (resumed with the same credential).
	FRESH='' PROBED=''
	if [ -f "$ROOT$CONF.pending" ]; then
		REGISTER="new (resuming the unfinished registration in $CONF.pending)"
	elif [ ! -f "$ROOT$CONF" ]; then
		REGISTER=new
	elif [ -n "$REREGISTER" ]; then
		REGISTER="existing (re-registration: rotates the credential and the loom token)"
	else
		# Registered already: ask the server whether it still knows this
		# responder, with a heartbeat probe (which records nothing), by curl
		# as for the download: nothing downloaded runs before confirmation.
		REGISTER=''
		CRED=$(awk '/^credential:/ { sub(/^credential: */, ""); print; exit }' "$ROOT$CONF" 2>/dev/null) || CRED=''
		case $CRED in
		orc1_*) case ${CRED#orc1_} in *[!A-Za-z0-9_-]* | '') CRED='' ;; esac ;;
		*) CRED='' ;;
		esac
		# curl reads a header from a file (-H @file) from 7.55 on; an older
		# one cannot ask without the credential on its argv, so it does not.
		CV=$(curl -q --version 2>/dev/null | awk 'NR == 1 { print $2 }') || CV=''
		CMAJ=${CV%%.*} CMIN=${CV#*.}
		CMIN=${CMIN%%.*}
		if [ -z "$CRED" ]; then
			REGISTER="new ($CONF holds no credential: register again)" FRESH=1
		elif ! is_digits "$CMAJ" || ! is_digits "$CMIN" || [ "$CMAJ" -lt 7 ] || { [ "$CMAJ" = 7 ] && [ "$CMIN" -lt 55 ]; }; then
			PROBED="the server could not be asked (curl ${CV:-?} is older than 7.55)"
		else
			# The credential reaches curl in a header file, never its argv.
			printf 'Authorization: Responder %s\n' "$CRED" >"$WORK/auth"
			CODE=$(curl -q -sS --proto '=https' -k --pinnedpubkey "$ORBIT_PIN" -o "$WORK/probe" -D "$WORK/probe.h" -w '%{http_code}' \
				-H 'Content-Type: application/json' -H "@$WORK/auth" --data '{"probe":true}' \
				"$ORBIT_SERVER/orbit.v1.JoinService/Heartbeat" 2>/dev/null) || CODE=''
			case $CODE in
			200) PROBED="known to the server" ;;
			401)
				if grep -qi '^orbit-responder-state: *removed' "$WORK/probe.h" 2>/dev/null; then
					REGISTER="new (credential removed by the server: register again)" FRESH=1
				else
					REGISTER="new (existing credential unknown to the server: register again)" FRESH=1
				fi
				;;
			*) PROBED="the server could not be asked (HTTP ${CODE:-none}): left as is" ;;
			esac
		fi
	fi

	# The systemd unit, its user and its helper. systemd 247 and later hand
	# the unit its config with LoadCredential, which it can read but not
	# replace (root:root 0600); older ones read it as the orbit user's own
	# file (orbit:orbit 0600).
	OWNER=''
	if [ -n "$NO_SYSTEMD" ]; then
		ok "systemd unit: skipped (--no-systemd)"
	elif [ ! -d "$ROOT/run/systemd/system" ]; then
		die "this host does not run systemd; rerun with --no-systemd (then run the responder yourself, and the route lasts until reboot)"
	else
		SDV=$(systemctl --version 2>/dev/null | awk 'NR == 1 { print $2 }') || SDV=''
		if is_digits "$SDV" && [ "$SDV" -ge 247 ]; then
			CREDLINE="LoadCredential=responder.yaml:$CONF"
			EXECCONF="\${CREDENTIALS_DIRECTORY}/responder.yaml"
		else
			CREDLINE=''
			EXECCONF=$CONF
			OWNER=orbit
			printf '  note: systemd %s is older than 247 (no LoadCredential): %s is owned by orbit, mode 0600\n' "${SDV:-?}" "$CONF" >>"$PLAN"
		fi
		if getent passwd orbit >/dev/null 2>&1; then
			ok "user orbit exists"
		else
			step "create the system user orbit, which the responder runs as"
			cmd "useradd --system --user-group --no-create-home --home-dir /nonexistent --shell /usr/sbin/nologin orbit"
		fi
		{
			echo "#!/bin/sh"
			echo "# orbit join: re-applies the N6 route and firewall rules for orbit-responder.service."
			echo "set -eu"
			echo "PATH=/usr/sbin:/usr/bin:/sbin:/bin"
			cat "$HELPER"
		} >"$WORK/join-net.sh"
		if cmp -s "$WORK/join-net.sh" "$ROOT$LIB/join-net.sh"; then
			ok "$LIB/join-net.sh is up to date"
		else
			step "install $LIB/join-net.sh (run as root before the responder starts):"
			while IFS= read -r L; do show "| $L"; done <"$WORK/join-net.sh"
			printf '%s || fail\n' "install -d -m 0755 '$ROOT$LIB'" "install -m 0755 '$WORK/join-net.sh' '$ROOT$LIB/join-net.sh'" >>"$APPLY"
		fi
		{
			cat <<EOF
[Unit]
Description=orbit N6 responder (orbit join)
Wants=network-online.target
After=network-online.target nftables.service iptables.service ip6tables.service netfilter-persistent.service

[Service]
User=orbit
Group=orbit
EOF
			[ -z "$CREDLINE" ] || echo "$CREDLINE"
			cat <<EOF
ExecStartPre=+$LIB/join-net.sh
ExecStart=$LIB/orbit responder --config $EXECCONF
Restart=on-failure
RestartPreventExitStatus=78
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
CapabilityBoundingSet=
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX

[Install]
WantedBy=multi-user.target
EOF
		} >"$WORK/unit"
		UNIT_CHANGED=''
		if cmp -s "$WORK/unit" "$ROOT$UNIT"; then
			ok "$UNIT is up to date"
		else
			UNIT_CHANGED=1
			step "install $UNIT:"
			while IFS= read -r L; do show "| $L"; done <"$WORK/unit"
			printf '%s || fail\n' "install -m 0644 '$WORK/unit' '$ROOT$UNIT'" "systemctl daemon-reload" >>"$APPLY"
		fi
	fi

	# The registration (ADR-0009 §3), by the installed orbit, as root.
	OWNERFLAG=''
	[ -z "$OWNER" ] || OWNERFLAG=" --owner $OWNER"
	[ -z "$FRESH" ] || OWNERFLAG="$OWNERFLAG --fresh"
	if [ -n "$REGISTER" ]; then
		step "register the responder on this host with the server as $NAME (credential: $REGISTER)"
		cmd "$(q "$ROOT$LIB/orbit") responder register --server $(q "$ORBIT_SERVER") --pin $(q "$ORBIT_PIN_RAW") --token-file $(q "$WORK/token") --name $(q "$NAME") --control $(q "$LISTEN") --data-ip $(q "$N6_IP") --data-ports $(q "$LO-$HI") --config $(q "$ROOT$CONF")$OWNERFLAG"
		show "(the join token is read from a file in this run's private directory, mode 0600)"
		if [ -n "$FRESH" ]; then
			show "(replaces $CONF and any $CONF.pending; an entry the server still holds for the old credential is left alone, and shows offline)"
		fi
	else
		ok "registered: $CONF is there, $PROBED (--reregister rotates its credential and loom token)"
	fi

	# Start it, and wait for the server to see it online.
	if [ -z "$NO_SYSTEMD" ]; then
		ENABLED=$(systemctl is-enabled orbit-responder 2>/dev/null) || ENABLED=''
		ACTIVE=$(systemctl is-active orbit-responder 2>/dev/null) || ACTIVE=''
		if [ -n "$REGISTER" ] || [ -n "$UNIT_CHANGED" ] || [ "$ENABLED" != enabled ] || [ "$ACTIVE" != active ]; then
			step "enable and (re)start orbit-responder, then wait for the server to see it online"
			echo "HINTS=yes" >>"$APPLY"
			cmd "systemctl enable orbit-responder"
			cmd "systemctl restart orbit-responder"
			cmd "$(q "$ROOT$LIB/orbit") responder check --config $(q "$ROOT$CONF") --wait 20s"
		else
			ok "orbit-responder is enabled and running"
		fi
	fi
	echo
	echo "Plan:"
	cat "$PLAN"
	if [ "$N" = 0 ]; then
		echo
		say "nothing to change"
		exit 0
	fi
	echo
	if [ -n "$DRY" ]; then
		say "dry run: nothing was changed"
		exit 0
	fi
	if [ -z "$YES" ]; then
		if (: <"$TTY") 2>/dev/null; then
			printf 'Apply %d changes? [y/N] ' "$N" >&2
			ANS=''
			read -r ANS <"$TTY" || ANS=''
			case $ANS in
			y | Y | yes | YES) ;;
			*)
				say "not applied: nothing on this host was changed"
				exit 0
				;;
			esac
		else
			say "no terminal to confirm on: nothing was changed. To apply, rerun with --yes (… | sudo sh -s -- --yes)"
			exit 0
		fi
	fi

	# The verified orbit runs for the first time only now, confirmed.
	chmod 0700 "$WORK/orbit"
	"$WORK/orbit" version >/dev/null || die "the downloaded orbit does not run on this host; nothing was changed"

	# Apply, step by step; a failure names the steps done and the one that
	# failed.
	DONE=0 CUR='' TITLE='' HINTS=''
	begin() {
		[ -z "$CUR" ] || DONE=$CUR
		CUR=$1 TITLE=$2
	}
	fail() {
		if [ -n "$HINTS" ]; then
			echo "orbit join: see why with: systemctl status orbit-responder; journalctl -u orbit-responder -n 20" >&2
			echo "orbit join: the registration stands: once fixed, systemctl restart orbit-responder (no new token needed)" >&2
		fi
		if [ "$DONE" = 0 ]; then
			echo "orbit join: step $CUR ($TITLE) failed; no step was applied" >&2
		elif [ "$DONE" = 1 ]; then
			echo "orbit join: step $CUR ($TITLE) failed; step 1 was applied" >&2
		else
			echo "orbit join: step $CUR ($TITLE) failed; steps 1-$DONE were applied" >&2
		fi
		exit 1
	}
	# shellcheck source=/dev/null # the apply file this run wrote
	. "$APPLY"
	say "applied $N changes."
	if [ -n "$NO_SYSTEMD" ]; then
		say "no systemd unit (--no-systemd): run the responder yourself, as an unprivileged user that can read $CONF: orbit responder --config $CONF"
	fi
}

main "$@" --orbit-end-00112233445566778899aabbccddeeff
